<script lang="ts">
  import { onDestroy, untrack } from 'svelte';
  import { ArrowLeft, Check, Database, Download, FolderOpen, RefreshCw, Search, ShieldCheck, Sparkles, UploadCloud } from '@lucide/svelte';
  import { app } from '$lib/stores/app.svelte';
  import { WorkbenchDataState, workbenchDataDrafts } from '$lib/workbench/data.svelte';
  import { dataCompatibility, dataExamples, dataMappingWarnings, dataSize } from '$lib/workbench/data';
  import type { DataConfig, DataSourceTab } from '$lib/workbench/dataTypes';
  import type { WorkbenchActionResult } from '$lib/workbench/actionResult';
  import type { WorkbenchTask } from '$lib/workbench/types';

  let { projectId, modelId, modelCreatedAt, task, graphText, connected, onBuild, imported = false }: { projectId: string; modelId: string; modelCreatedAt: string; task: WorkbenchTask; graphText: string; connected: boolean; onBuild: () => void; imported?: boolean } = $props();
  const data = new WorkbenchDataState((method, params, timeout) => app.call(method, params, timeout), () => graphText, workbenchDataDrafts, () => modelCreatedAt);
  let query = $state(''), repo = $state(''), token = $state(''), dragging = $state(false);
  let filesInput = $state<HTMLInputElement>(), folderInput = $state<HTMLInputElement>();
  const sources: { id: DataSourceTab; name: string }[] = [{ id: 'examples', name: 'Examples' }, { id: 'local', name: 'Local files' }, { id: 'huggingface', name: 'Hugging Face' }];
  $effect(() => { const context = { projectId, modelId, task, connected }; untrack(() => { token = ''; void data.activate(context.projectId, context.modelId, context.task, context.connected); }); });
  $effect(() => { const source = data.source; void projectId; void modelId; const online = connected; untrack(() => { token = ''; if (source === 'huggingface' && online) void data.accountAction('status'); }); });
  $effect(() => { const id=projectId, model=modelId, version=modelCreatedAt; const changed=(event:Event) => { const result=(event as CustomEvent<WorkbenchActionResult>).detail; if (result?.projectId===id && result.modelId===model && result.modelCreatedAt===version && result.action==='save_data') void data.load(result.datasetId); }; window.addEventListener('umcode:workbench-action',changed); return () => window.removeEventListener('umcode:workbench-action',changed); });
  onDestroy(() => { token = ''; data.dispose(); });
  const dataset = $derived(data.dataset), config = $derived(data.config);
  const compatibility = $derived(dataset && config ? dataCompatibility(graphText, dataset, config, data.selection) : []);
  const mappingWarnings = $derived(dataset && config ? dataMappingWarnings(dataset, config) : []);
  const numericColumns = $derived(dataset?.columns.filter(c => c.kind === 'number') ?? []);
  const missing = $derived(dataset?.columns.reduce((sum, c) => sum + c.missing, 0) ?? 0);
  const selectedBytes = $derived(data.repository?.files.filter(file => data.selectedFiles.includes(file.name)).reduce((sum, file) => sum + file.size, 0) ?? 0);
  function source(id: DataSourceTab) { token = ''; data.changeSource(id); }
  function chooseFiles(event: Event) { const input = event.currentTarget as HTMLInputElement; const files = Array.from(input.files ?? []); input.value = ''; if (files.length) void data.importLocal(files); }
  function drop(event: DragEvent) { event.preventDefault(); dragging = false; if (connected && !data.busy) void data.importLocal(Array.from(event.dataTransfer?.files ?? [])); }
  function setMode(mode: DataConfig['mode']) {
    if (!dataset || !config) return;
    const kind = mode === 'features' ? 'number' : mode === 'image' ? 'image' : 'text';
    const candidates = dataset.columns.filter(c => c.kind === kind && c.name !== config.targetColumn);
    data.updateConfig({ mode, inputColumns: mode === 'features' ? candidates.filter(c => !/(^|_)(id|index|uuid)$/i.test(c.name)).map(c => c.name) : candidates.slice(0, 1).map(c => c.name) });
  }
  function toggleInput(name: string, checked: boolean) { if (config) data.updateConfig({ inputColumns: checked ? [...config.inputColumns, name] : config.inputColumns.filter(c => c !== name) }); }
  function connectToken(event: SubmitEvent) { event.preventDefault(); const secret = token.trim(); token = ''; if (secret) void data.accountAction('connect', secret); }
  function numberSetting(key: keyof DataConfig, value: number) { data.updateConfig({ [key]: value }); }
</script>

<section class="data-tab" data-data-tab aria-label="Model data">
  <div class="data-heading"><div><h2>Give your model something to learn</h2><p>Bring your data, explore Hugging Face, or start with an example.</p></div><span class="local-badge"><ShieldCheck size={13} />Local data</span></div>
  <div class="source-row" role="group" aria-label="Dataset source">
    {#each sources as item}<button class="source-button" class:is-selected={data.source === item.id} aria-pressed={data.source === item.id} onclick={() => source(item.id)}>{#if item.id === 'examples'}<Sparkles size={14} />{:else if item.id === 'local'}<FolderOpen size={14} />{:else}<Database size={14} />{/if}{item.name}</button>{/each}
    <span class="later-note">More hubs later</span>
  </div>

  {#if data.source === 'examples'}
    <div class="example-grid">
      {#each dataExamples as example}<article class="example-card"><div class="card-top"><span>Hugging Face · public</span><Database size={15} /></div><h3>{example.name}</h3><p>{example.description}</p><code>{example.source.repo}</code><button class="btn-outline btn-sm" disabled={!connected || data.busy} onclick={() => void data.importData(example.source)}><Download size={13} />Import example</button></article>{/each}
    </div>
    <p class="source-note">Examples download real files at a pinned revision. Review the imported columns and choose your target.</p>
  {:else if data.source === 'local'}
    <section class="upload-area" class:is-dragging={dragging} aria-label="Upload local files" ondragover={(event) => { event.preventDefault(); dragging = true; }} ondragleave={() => dragging = false} ondrop={drop}>
      <UploadCloud size={28} strokeWidth={1.4} /><h3>Drop CSV, TSV, JSONL or text files</h3><p>For images, choose a PNG/JPEG folder with one subfolder per label.</p>
      <div class="upload-buttons"><button class="btn-outline btn-sm" disabled={!connected || data.busy} onclick={() => filesInput?.click()}>Choose files</button><button class="btn-outline btn-sm" disabled={!connected || data.busy} onclick={() => folderInput?.click()}><FolderOpen size={13} />Choose image folder</button></div>
      <input bind:this={filesInput} type="file" accept=".csv,.tsv,.jsonl,.txt,.png,.jpg,.jpeg" multiple onchange={chooseFiles} hidden />
      <input bind:this={folderInput} type="file" accept=".png,.jpg,.jpeg" webkitdirectory multiple onchange={chooseFiles} hidden />
      <p class="source-note">16 MiB total · 1,000 files · 100,000 rows · 128 columns. File bytes go only to your local engine.</p>
    </section>
  {:else}
    <div class="hf-account"><div><strong>Hugging Face</strong><p>{data.account.connected ? `Connected as ${data.account.username}` : 'Public, ungated datasets work without a token.'}</p></div>
      {#if data.account.connected}<button class="btn-outline btn-sm" disabled={!connected || data.accountBusy} onclick={() => void data.accountAction('disconnect')}>Disconnect token</button>
      {:else}<form class="token-form" onsubmit={connectToken}><label class="sr-only" for="hf-read-token">Hugging Face read token</label><input id="hf-read-token" class="input" type="password" bind:value={token} placeholder="Optional read token" autocomplete="off" spellcheck="false" disabled={!connected || data.accountBusy} /><button class="btn-outline btn-sm" disabled={!connected || data.accountBusy || !token.trim()}>Connect token</button></form>{/if}
    </div>
    <form class="search-row" onsubmit={(event) => { event.preventDefault(); void data.search(query); }}><label class="sr-only" for="hf-data-search">Search Hugging Face datasets</label><Search size={15} /><input id="hf-data-search" class="input" type="search" bind:value={query} placeholder="Search datasets or an owner, e.g. nprak26" /><button class="btn-outline btn-sm" disabled={!connected || data.busy || !query.trim()}>Search</button></form>
    <form class="repo-row" onsubmit={(event) => { event.preventDefault(); void data.inspect(repo); }}><label for="hf-data-repo">Or open a repository</label><input id="hf-data-repo" class="input" bind:value={repo} placeholder="owner/dataset" /><button class="btn-outline btn-sm" disabled={!connected || data.busy || !repo.trim()}>Inspect files</button></form>
    {#if data.results.length}<div class="hf-results" aria-label="Dataset search results">{#each data.results as result}<button class="hf-result" disabled={!connected || data.busy} onclick={() => { repo = result.id; void data.inspect(result.id); }}><strong>{result.id}</strong><span>{result.downloads.toLocaleString()} downloads · {result.likes.toLocaleString()} likes{result.gated ? ' · gated' : ''}{result.private ? ' · private' : ''}</span><span>Inspect files →</span></button>{/each}</div>{/if}
    {#if data.repository}
      <section class="repository" aria-label="Repository files"><div class="section-heading"><div><h3>{data.repository.id}</h3><p>Revision <code>{data.repository.sha}</code>{data.repository.license ? ` · License: ${data.repository.license}` : ''}</p></div><span class="tag">{data.repository.private ? 'Private' : data.repository.gated ? 'Gated' : 'Public'}</span></div>
        {#if data.repository.gated}<p class="source-note">This repository may require access approval on Hugging Face and a read token.</p>{/if}
        <div class="repository-files">{#each data.repository.files as file}<label class="file-option"><input type="checkbox" checked={data.selectedFiles.includes(file.name)} disabled={!file.supported || data.busy || !connected} onchange={(event) => data.toggleFile(file.name, event.currentTarget.checked)} /><span>{file.name}{#if !file.supported}<small>Unsupported format</small>{/if}</span><span>{dataSize(file.size)}</span></label>{/each}</div>
        {#if !data.repository.files.some(file => file.supported)}<p class="warning">No supported native files. Parquet, audio, nested annotations, archives and dataset scripts cannot be imported in this version.</p>{/if}
        <div class="repository-footer"><span>{data.selectedFiles.length} selected · {dataSize(selectedBytes)} · 16 MiB limit</span><button class="btn-primary btn-sm" disabled={!connected || data.busy || !data.selectedFiles.length || selectedBytes > 16 * 1024 * 1024 || data.selectedFiles.length > 1000} onclick={() => void data.importRepository()}><Download size={13} />Import selected files</button></div>
      </section>
    {/if}
    <p class="source-note">Only native CSV, TSV, JSONL, TXT, PNG and JPEG files are imported. Dataset code is never executed. Tokens are stored by the local engine, outside project files.</p>
  {/if}

  {#if data.stage}<div class="feedback loading" role="status"><RefreshCw size={13} class="spinner" />{data.stage}</div>{/if}
  {#if data.error}<div class="feedback error" role="alert">{data.error}</div>{/if}
  {#if data.notice}<div class="feedback" role="status">{data.notice}</div>{/if}
  <div class="imported-row"><label for="imported-dataset">Imported datasets</label><select id="imported-dataset" class="select" value={dataset?.id ?? ''} disabled={!connected || data.busy || !data.datasets.length} onchange={(event) => void data.selectDataset(event.currentTarget.value)}><option value="">Choose an imported dataset</option>{#each data.datasets as imported}<option value={imported.id}>{imported.name} · {imported.rowCount.toLocaleString()} rows</option>{/each}</select><button class="icon-button" aria-label="Refresh imported datasets" disabled={!connected || data.busy} onclick={() => void data.load(dataset?.id)}><RefreshCw size={14} /></button></div>

  {#if dataset && config}
    <div class="data-workspace">
      <div class="data-details">
        <div class="section-heading"><div><span class="eyebrow">Imported dataset</span><h3>{dataset.name}</h3></div><span class="tag"><Check size={12} />Imported</span></div>
        <p class="dataset-meta">{dataset.rowCount.toLocaleString()} rows · {dataset.columns.length} columns · {dataSize(dataset.byteCount)} · {missing.toLocaleString()} missing cells</p>
        <p class="dataset-provenance">{dataset.source.kind === 'local' ? 'Local files' : 'Hugging Face'}{dataset.source.repo ? ` · ${dataset.source.repo}` : ''}{#if dataset.source.revision}<br />Revision <code>{dataset.source.revision}</code>{/if}</p>
        <!-- svelte-ignore a11y_no_noninteractive_tabindex (Keyboard users need to focus this overflowing table to scroll its columns.) -->
        <div class="table-scroll" tabindex="0" role="region" aria-label="Actual imported row preview"><table><caption>Actual imported rows · showing {Math.min(dataset.preview?.length ?? 0, 20)} of {dataset.rowCount.toLocaleString()} · cells truncated at 256 characters</caption><thead><tr>{#each dataset.columns as column}<th scope="col">{column.name}<span>{column.kind} · {column.missing} missing</span></th>{/each}</tr></thead><tbody>{#each (dataset.preview ?? []).slice(0, 20) as row}<tr>{#each dataset.columns as column}<td title={row[column.name] ?? ''}>{row[column.name] ?? ''}</td>{/each}</tr>{/each}</tbody></table></div>
        <section class="split-section" aria-labelledby="data-splits"><div class="section-heading"><h3 id="data-splits">Train / validation / test</h3><span>{config.trainPercent}% / {config.validationPercent}% / {config.testPercent}%</span></div>
          <div class="split-bar" role="img" aria-label={`${config.trainPercent}% training, ${config.validationPercent}% validation, ${config.testPercent}% test`}><span style:width={`${Math.max(0, Math.min(100, config.trainPercent))}%`}></span><span style:width={`${Math.max(0, Math.min(100, config.validationPercent))}%`}></span><span style:width={`${Math.max(0, Math.min(100, config.testPercent))}%`}></span></div>
          <div class="split-fields">{#each [{ key: 'trainPercent', label: 'Train %' }, { key: 'validationPercent', label: 'Validation %' }, { key: 'testPercent', label: 'Test %' }, { key: 'seed', label: 'Split seed' }] as field}<label>{field.label}<input class="input" type="number" min="0" max={field.key === 'seed' ? undefined : 100} step="1" value={config[field.key as 'trainPercent' | 'validationPercent' | 'testPercent' | 'seed']} onchange={(event) => numberSetting(field.key as keyof DataConfig, event.currentTarget.valueAsNumber)} /></label>{/each}</div>
          {#if config.purpose === 'classification'}<label class="check-option"><input type="checkbox" checked={config.stratify} onchange={(event) => data.updateConfig({ stratify: event.currentTarget.checked })} />Keep label proportions across splits</label>{/if}
          <p class="source-note">Splits use a deterministic seed. Numeric normalization is fitted on training rows only.</p>
        </section>
        {#if data.selection}<section class="saved-preparation"><div class="section-heading"><h3>Saved preparation</h3><span class="tag">{data.dirty ? 'Mapping changed' : 'Saved'}</span></div><p>Version <code>{data.selection.version}</code></p><p>{data.selection.counts.train.toLocaleString()} train · {data.selection.counts.validation.toLocaleString()} validation · {data.selection.counts.test.toLocaleString()} test</p>{#if data.selection.classes?.length}<p>Classes: {data.selection.classes.join(', ')}</p>{/if}{#each data.selection.warnings ?? [] as warning}<p class="warning">{warning}</p>{/each}<p class="source-note">Stored with this model and used for local training and checkpoint input preparation.</p></section>{/if}
      </div>
      <aside class="data-setup" aria-label="Prepare dataset"><h3>Prepare for your model</h3>
        <label for="data-input-mode">Input type</label><select id="data-input-mode" class="select" value={config.mode} onchange={(event) => setMode(event.currentTarget.value as DataConfig['mode'])}>{#if dataset.format === 'images'}<option value="image">Images</option>{:else}<option value="text">Text</option>{#if numericColumns.length && task !== 'text-generation'}<option value="features">Numeric features</option>{/if}{/if}</select>
        {#if task === 'custom'}<label for="data-purpose">Prediction</label><select id="data-purpose" class="select" value={config.purpose} onchange={(event) => data.updateConfig({ purpose: event.currentTarget.value as DataConfig['purpose'], stratify: event.currentTarget.value === 'classification' })}><option value="classification">Classification</option><option value="regression">Regression</option>{#if config.mode === 'text'}<option value="text-generation">Text generation</option>{/if}</select>{/if}
        <label for="data-target">{config.purpose === 'text-generation' ? 'Response column (optional)' : 'Target column'}</label><select id="data-target" class="select" value={config.targetColumn} onchange={(event) => data.updateConfig({ targetColumn: event.currentTarget.value })}><option value="">{config.purpose === 'text-generation' ? 'No response · text corpus' : 'Choose a target'}</option>{#each dataset.columns.filter(c => c.kind !== 'image') as column}<option value={column.name}>{column.name} · {column.uniqueCount} distinct</option>{/each}</select>
        {#if config.mode === 'features'}<fieldset><legend>Numeric input fields ({config.inputColumns.length})</legend><div class="input-checks">{#each numericColumns as column}<label class="check-option"><input type="checkbox" checked={config.inputColumns.includes(column.name)} disabled={column.name === config.targetColumn} onchange={(event) => toggleInput(column.name, event.currentTarget.checked)} /><span>{column.name}{#if column.name === config.targetColumn}<small>Target · excluded</small>{/if}</span></label>{/each}</div></fieldset><label for="data-scale">Preparation</label><select id="data-scale" class="select" value={config.scale} onchange={(event) => data.updateConfig({ scale: event.currentTarget.value as DataConfig['scale'] })}><option value="none">Keep numeric scale</option><option value="standard">Standardize numeric features</option></select>
        {:else}<label for="data-input-column">{config.mode === 'text' ? 'Text / prompt column' : 'Image column'}</label><select id="data-input-column" class="select" value={config.inputColumns[0] ?? ''} onchange={(event) => data.updateConfig({ inputColumns: event.currentTarget.value ? [event.currentTarget.value] : [] })}><option value="">Choose an input</option>{#each dataset.columns.filter(c => c.kind === (config.mode === 'text' ? 'text' : 'image') && c.name !== config.targetColumn) as column}<option value={column.name}>{column.name}</option>{/each}</select>
          {#if config.mode === 'text'}<label for="data-sequence">Sequence length</label><input id="data-sequence" class="input" type="number" min="3" max={imported ? 2048 : 8192} step="1" value={config.sequenceLength} onchange={(event) => numberSetting('sequenceLength', event.currentTarget.valueAsNumber)} /><p class="source-note">{imported ? 'Uses the imported model’s tokenizer. Text is preserved for tokenization during training; the model vocabulary is unchanged.' : 'UTF-8 byte tokenizer · vocabulary 259. PAD=0, BOS=1, EOS=2, bytes + 3. This is not a pretrained tokenizer.'}</p>
          {:else if imported}<p class="source-note">Uses the imported image processor for resizing, channels and normalization. Image labels must match the pretrained labels or their numeric indices.</p>{:else}<div class="image-fields">{#each [{ key: 'imageWidth', label: 'Width' }, { key: 'imageHeight', label: 'Height' }] as field}<label>{field.label}<input class="input" type="number" min="1" max="4096" step="1" value={config[field.key as 'imageWidth' | 'imageHeight']} onchange={(event) => numberSetting(field.key as keyof DataConfig, event.currentTarget.valueAsNumber)} /></label>{/each}</div><label for="data-channels">Image channels</label><select id="data-channels" class="select" value={config.imageChannels} onchange={(event) => numberSetting('imageChannels', Number(event.currentTarget.value))}><option value={3}>3 · RGB</option><option value={1}>1 · Grayscale</option></select><p class="source-note">Saves source images and their input preparation. Image training is not available in this version.</p>{/if}
        {/if}
        {#if config.purpose === 'classification' && config.targetColumn}<p class="label-summary">{dataset.columns.find(c => c.name === config.targetColumn)?.uniqueCount ?? 0} distinct target values. Examples: {dataset.columns.find(c => c.name === config.targetColumn)?.examples?.join(', ')}</p>{/if}
        {#if mappingWarnings.length}<div class="validation" role="status"><strong>Review these fields</strong><ul>{#each mappingWarnings as warning}<li>{warning}</li>{/each}</ul></div>{/if}
        {#if data.validation.length}<div class="validation" role="status"><strong>Check preparation</strong><ul>{#each data.validation as issue}<li>{issue}</li>{/each}</ul></div>{/if}
        <div class="compatibility selectable" class:has-issues={compatibility.length > 0}><strong>{compatibility.length ? 'Review in Build' : imported ? 'Uses imported preprocessing' : 'Current graph dimensions match'}</strong>{#if compatibility.length}<ul>{#each compatibility as issue}<li>{issue}</li>{/each}</ul>{/if}<button class="btn-ghost btn-sm" onclick={onBuild}><ArrowLeft size={13} />Back to Build</button></div>
        <button class="btn-primary save-preparation" disabled={!connected || data.busy || data.validation.length > 0 || !data.dirty} onclick={() => void data.prepare()}>{data.stage === 'Saving preparation…' ? 'Saving preparation…' : data.selection && !data.dirty ? 'Preparation saved' : 'Save preparation'}</button><p class="source-note">Saves data settings separately from the model graph. You can save while graph issues remain; resolve them in Build before starting training.</p>
      </aside>
    </div>
  {:else if !data.busy}<div class="empty-data"><Database size={23} strokeWidth={1.4} /><p>{data.source === 'local' ? 'No local dataset selected. Choose files to import and preview actual rows.' : 'Import a dataset above or choose one already imported into this model.'}</p></div>{/if}
</section>

<style>
  .data-tab { flex:1; min-width:0; min-height:0; overflow:auto; padding:22px 24px 28px; font-size:12px; }
  .data-heading, .section-heading { display:flex; gap:12px; justify-content:space-between; align-items:center; }
  h2 { font-size:20px; font-weight:650; line-height:1.4; } h3 { font-size:13px; font-weight:650; line-height:1.5; }
  .data-heading p { color:var(--color-muted); margin-top:5px; line-height:1.6; }
  .local-badge { display:flex; gap:5px; align-items:center; color:var(--color-muted); font-size:10px; white-space:nowrap; }
  .source-row { display:flex; align-items:center; gap:6px; flex-wrap:wrap; margin:20px 0 16px; }
  .source-button { display:flex; gap:7px; align-items:center; padding:8px 12px; border:1px solid var(--color-line); background:var(--color-paper); border-radius:7px; font-size:12px; }
  .source-button:hover, .source-button.is-selected { border-color:var(--color-accent); } .source-button.is-selected { color:var(--color-accent-strong); background:var(--color-accent-soft); }
  .later-note { color:var(--color-muted); font-size:10px; margin-left:6px; }
  .example-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; }
  .example-card { border:1px solid var(--color-line); border-radius:10px; background:var(--color-paper); padding:14px; display:flex; flex-direction:column; gap:9px; min-width:0; }
  .card-top { display:flex; justify-content:space-between; color:var(--color-muted); font-size:10px; }
  .example-card p { color:var(--color-ink-soft); line-height:1.6; } .example-card code { font-size:10px; color:var(--color-muted); overflow-wrap:anywhere; margin-bottom:auto; } .example-card button { align-self:flex-start; margin-top:4px; }
  .source-note { color:var(--color-muted); font-size:10px; line-height:1.7; margin-top:10px; }
  .upload-area { border:1px dashed var(--color-line); border-radius:10px; padding:27px 18px; display:flex; flex-direction:column; align-items:center; gap:9px; text-align:center; background:var(--color-surface); }
  .upload-area.is-dragging { border-color:var(--color-accent); background:var(--color-accent-soft); } .upload-area > p { color:var(--color-muted); line-height:1.7; } .upload-buttons { display:flex; justify-content:center; flex-wrap:wrap; gap:8px; margin-top:5px; }
  .hf-account { border:1px solid var(--color-line); border-radius:8px; background:var(--color-surface); padding:12px; display:flex; align-items:center; justify-content:space-between; gap:12px; } .hf-account p { font-size:11px; color:var(--color-muted); margin-top:4px; }
  .token-form, .search-row, .repo-row { display:flex; gap:8px; align-items:center; min-width:0; } .token-form input { width:175px; min-width:0; } .token-form button { flex-shrink:0; }
  .search-row { margin-top:14px; } .search-row input, .repo-row input { min-width:0; flex:1; } .repo-row { margin-top:10px; } .repo-row label { color:var(--color-muted); font-size:11px; }
  .hf-results { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px; margin-top:14px; max-height:240px; overflow:auto; }
  .hf-result { display:flex; flex-direction:column; align-items:flex-start; text-align:left; gap:5px; border:1px solid var(--color-line); border-radius:7px; padding:12px; background:var(--color-paper); min-width:0; overflow-wrap:anywhere; } .hf-result:hover { border-color:var(--color-accent); } .hf-result span { color:var(--color-muted); font-size:10px; }
  .repository { margin-top:14px; padding:14px; border:1px solid var(--color-line); border-radius:9px; } .repository .section-heading { align-items:flex-start; } .repository p { font-size:10px; color:var(--color-muted); margin-top:6px; overflow-wrap:anywhere; line-height:1.7; }
